import type { ContentType } from "@/lib/types";
import type { LengthId, ToneId } from "@/lib/ai/options";
import { analyseSeo, type SeoReport } from "./analyse";

/**
 * SEO outline planning.
 *
 * The outline is derived from the analysis, not generated by a model: the
 * heading suggestions come from the keyword and the words around it. This keeps
 * the tool useful even when no provider key is set, and means the suggested
 * structure is always traceable to the text the writer supplied.
 */

export interface SeoOutlineSection {
  title: string;
  /** Why this section is suggested, shown to the writer. */
  rationale: string;
  wordTarget: number;
}

export interface SeoPlan {
  keyword: string;
  sections: SeoOutlineSection[];
  /** Guidance lines that map to the failing checks in the report. */
  priorities: string[];
  report: SeoReport;
}

const TARGET_TOTALS: Record<LengthId, number> = {
  short: 500,
  medium: 1100,
  long: 2000,
  custom: 1100,
};

/** Title-case a keyword without destroying acronyms or short words. */
export function titleCaseKeyword(keyword: string): string {
  const minor = new Set(["a", "an", "and", "for", "in", "of", "on", "or", "the", "to", "with"]);
  return keyword
    .split(" ")
    .map((word, index) => {
      if (word.length === 0) return word;
      // Leave words that already look deliberate: all caps, or containing digits.
      if (word === word.toUpperCase() && word.length > 1) return word;
      if (/\d/.test(word)) return word;
      if (index > 0 && minor.has(word)) return word;
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join(" ");
}

/**
 * A stable set of section shapes for a keyword. Every section is phrased so the
 * writer knows what to put in it; none of them is a filler heading.
 */
export function buildSeoOutline(
  keyword: string,
  report: SeoReport,
): SeoOutlineSection[] {
  const phrase = keyword.trim();
  if (!phrase) return [];
  const label = titleCaseKeyword(phrase);

  const sections: SeoOutlineSection[] = [
    {
      title: `${label}: what it is and why it matters`,
      rationale: "Opens with the keyword in the first heading and the first paragraph.",
      wordTarget: 200,
    },
    {
      title: `How ${phrase} works in practice`,
      rationale: "Covers the mechanism, which is what readers search to understand.",
      wordTarget: 300,
    },
    {
      title: `Common mistakes with ${phrase}`,
      rationale: "Answers a follow-up question readers ask next.",
      wordTarget: 300,
    },
    {
      title: `Choosing the right approach to ${phrase}`,
      rationale: "Gives the piece a decision to help with, not just information.",
      wordTarget: 300,
    },
    {
      title: `${label}: key takeaways`,
      rationale: "Closes with a summary, which is what gets quoted and linked.",
      wordTarget: 150,
    },
  ];

  // If the draft already covers the topic in a heading, do not suggest a
  // duplicate; keep only the sections that add something.
  const existing = report.headings.map((heading) => heading.text.toLowerCase());
  const filtered = sections.filter((section) => {
    const words = phrase.toLowerCase().split(/\s+/);
    return !existing.some(
      (heading) => words.every((word) => heading.includes(word)) &&
        heading.includes(section.title.toLowerCase().split(":")[0]!.trim()),
    );
  });

  return filtered.length >= 3 ? filtered : sections;
}

/** Priorities derived from failing checks, in the order they should be fixed. */
export function buildPriorities(report: SeoReport): string[] {
  const priorities: string[] = [];
  for (const check of report.checks) {
    if (check.status !== "pass" && check.advice) priorities.push(check.advice);
  }
  return priorities;
}

export function planSeo(input: {
  topic: string;
  keyword: string;
  contentType: ContentType;
  tone: ToneId;
  length: LengthId;
  draft?: string;
}): SeoPlan {
  const draft = input.draft ?? "";
  const report = analyseSeo({ text: draft, keyword: input.keyword });
  const sections = buildSeoOutline(input.keyword, report);

  // Scale the suggested targets to the requested length.
  const total = TARGET_TOTALS[input.length] ?? 1100;
  const baseTotal = sections.reduce((sum, section) => sum + section.wordTarget, 0) || 1;
  const scaled = sections.map((section) => ({
    ...section,
    wordTarget: Math.max(80, Math.round((section.wordTarget / baseTotal) * total)),
  }));

  return {
    keyword: input.keyword.trim(),
    sections: scaled,
    priorities: buildPriorities(report),
    report,
  };
}
